import re
import sys

import openpyxl
from openpyxl.styles import Font

FILE = 'sales_data.xlsx'


def norm(v):
    if v is None:
        return ''
    return str(v).strip().lower()


def find_headers(ws):
    for r in range(1, min(ws.max_row, 20) + 1):
        vals = [ws.cell(row=r, column=c).value for c in range(1, ws.max_column + 1)]
        if any(norm(v) for v in vals):
            return r, vals
    return 1, [ws.cell(row=1, column=c).value for c in range(1, ws.max_column + 1)]


def main():
    wb = openpyxl.load_workbook(FILE)
    ws = wb.active
    header_row, headers = find_headers(ws)
    print(f"Sheet: {ws.title}, dims: {ws.dimensions}, header_row: {header_row}")

    rev_idx = None
    cost_idx = None
    profit_idx = None
    for i, h in enumerate(headers, start=1):
        hh = norm(h)
        print(f"  col {i}: {h!r}")
        if rev_idx is None and re.search(r'revenue|sales|price|amount', hh):
            rev_idx = i
        if cost_idx is None and re.search(r'cost|cogs|expense|spend', hh):
            cost_idx = i
        if profit_idx is None and re.search(r'profit|margin|income|gross', hh) and 'margin' not in hh:
            profit_idx = i

    if profit_idx is not None:
        num = f'{openpyxl.utils.get_column_letter(profit_idx)}' + '{r}'
        formula = f'=IFERROR({num}/$x$1,0)'
        print(f"profit column detected: {profit_idx}")
    elif rev_idx is not None and cost_idx is not None:
        formula = ('=IFERROR(('
                   + f'{openpyxl.utils.get_column_letter(rev_idx)}' + '{r}-'
                   + f'{openpyxl.utils.get_column_letter(cost_idx)}' + '{r})/'
                   + f'{openpyxl.utils.get_column_letter(rev_idx)}' + '{r},0)')
        print(f"revenue={rev_idx}, cost={cost_idx}")
    else:
        print("ERROR: could not identify needed columns")
        sys.exit(1)

    new_col = ws.max_column + 1
    new_letter = openpyxl.utils.get_column_letter(new_col)
    ws.cell(row=header_row, column=new_col, value='Profit Margin')
    ws.cell(row=header_row, column=new_col).font = Font(bold=True)
    for r in range(header_row + 1, ws.max_row + 1):
        if any(ws.cell(row=r, column=c).value is not None for c in range(1, new_col)):
            cell = ws.cell(row=r, column=new_col)
            if profit_idx is not None:
                cell.value = formula.format(r=r).replace('$x$1', openpyxl.utils.get_column_letter(profit_idx))
            else:
                cell.value = formula.format(r=r)
            cell.number_format = '0.0%'
    wb.save(FILE)
    print(f"Added column {new_letter} (Profit Margin) with formulas; saved {FILE}")


if __name__ == '__main__':
    main()

